INSERT INTO public.relay_doc_category (id, title, sort_order, enabled, created_at, updated_at) VALUES (1, '准备工作', 0, true, '2026-09-13 14:36:23.681059+08', '2026-09-13 14:36:23.681059+08');
INSERT INTO public.relay_doc_category (id, title, sort_order, enabled, created_at, updated_at) VALUES (2, '安装激活', 2, true, '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08');
INSERT INTO public.relay_doc_category (id, title, sort_order, enabled, created_at, updated_at) VALUES (3, '常见问题', 3, true, '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08');
INSERT INTO public.relay_doc_article (id, category_id, title, slug, content_html, sort_order, status, published_at, created_at, updated_at) VALUES (4, 3, '续单后如何更换卡密？', 'faq-renew-key', '<p>在原绑定机器的 IDE 内解绑，然后绑定新购买的 CDK 卡密。</p><blockquote><p><strong>【图片占位：解绑旧卡密并绑定新卡密】</strong></p></blockquote>', 1, 'PUBLISHED', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08');
INSERT INTO public.relay_doc_article (id, category_id, title, slug, content_html, sort_order, status, published_at, created_at, updated_at) VALUES (6, 3, '为什么感觉模型变弱了？', 'faq-model-quality', '<p>工具调用链路与官方一致，走 AWS 渠道；插件内也有地址，懂逆向的用户可以自行测试。</p>', 3, 'PUBLISHED', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08');
INSERT INTO public.relay_doc_article (id, category_id, title, slug, content_html, sort_order, status, published_at, created_at, updated_at) VALUES (7, 3, '为什么报 400 错误？', 'faq-400', '<p>通常是上下文压缩异常。可以新建一个会话或任务后再尝试。</p>', 4, 'PUBLISHED', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08');
INSERT INTO public.relay_doc_article (id, category_id, title, slug, content_html, sort_order, status, published_at, created_at, updated_at) VALUES (8, 3, '为什么不显示模型？', 'faq-no-models', '<p>尝试把插件和 Kiro IDE 都更新到最新版本，然后完全退出并关闭本地 VPN 代理，再重启 Kiro 尝试。</p>', 5, 'PUBLISHED', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08');
INSERT INTO public.relay_doc_article (id, category_id, title, slug, content_html, sort_order, status, published_at, created_at, updated_at) VALUES (9, 3, '怎么清理这个插件？', 'faq-clean-plugin', '<p>到 Kiro IDE 的 <code>settings.json</code> 配置文件中移除此插件相关配置，然后重启 IDE。</p><blockquote><p><strong>【图片占位：扩展设置中需清理的配置】</strong></p></blockquote><blockquote><p><strong>【图片占位：settings.json 清理示例】</strong></p></blockquote><p>也可使用一键清理工具。</p>', 6, 'PUBLISHED', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08');
INSERT INTO public.relay_doc_article (id, category_id, title, slug, content_html, sort_order, status, published_at, created_at, updated_at) VALUES (10, 3, '为什么新安装后显示需要登录账户？', 'faq-account-required', '<p>在个人目录下创建一个 <code>.aws</code> 目录即可，或者登录自己的账号（账号无要求，新注册也可以）。</p><blockquote><p><strong>【图片占位：Kiro 登录页与 .aws 目录处理】</strong></p></blockquote>', 7, 'PUBLISHED', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08');
INSERT INTO public.relay_doc_article (id, category_id, title, slug, content_html, sort_order, status, published_at, created_at, updated_at) VALUES (11, 3, '为什么首次打开 Kiro 显示让我登录？', 'faq-first-login', '<p>首次进入需登录 Kiro IDE 即可。账号无任何要求，使用任意账号即可。</p>', 8, 'PUBLISHED', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08');
INSERT INTO public.relay_doc_article (id, category_id, title, slug, content_html, sort_order, status, published_at, created_at, updated_at) VALUES (12, 3, '为什么模型选择会自动变？', 'faq-model-switch', '<p>在设置中把对应模型选择设置重置为空，然后重新选择需要使用的模型。</p><blockquote><p><strong>【图片占位：模型选择重置为空】</strong></p></blockquote>', 9, 'PUBLISHED', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08');
INSERT INTO public.relay_doc_article (id, category_id, title, slug, content_html, sort_order, status, published_at, created_at, updated_at) VALUES (13, 3, '为什么连接非常慢，甚至有时会卡住？', 'faq-slow-connection', '<p>可以更换本地 DNS，主 DNS 使用 <code>1.1.1.1</code>，备用 DNS 使用 <code>223.5.5.5</code>。</p><p>如需使用自动修改脚本，请在后台编辑本章时补充下载地址。</p>', 10, 'PUBLISHED', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08');
INSERT INTO public.relay_doc_article (id, category_id, title, slug, content_html, sort_order, status, published_at, created_at, updated_at) VALUES (2, 1, '需要准备的内容', 'quick-start', '<h2>📦 需要准备的内容</h2><ul><li>已购买的 Kiro 卡密</li><li>一台能联网的电脑（Windows / macOS / Linux 桌面版）</li><li>大约 5–10 分钟时间</li></ul>', 0, 'PUBLISHED', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08', '2026-09-13 23:40:25.525143+08');
INSERT INTO public.relay_doc_article (id, category_id, title, slug, content_html, sort_order, status, published_at, created_at, updated_at) VALUES (5, 3, '为什么消耗这么快？', 'faq-usage', '<p>Opus 官方消耗为 2.2 倍，当前扩展工具会在此基础上增加 0.2–0.4 倍率，作为服务差价。</p>', 2, 'PUBLISHED', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08', '2026-09-14 01:05:41.72926+08');
INSERT INTO public.relay_doc_article (id, category_id, title, slug, content_html, sort_order, status, published_at, created_at, updated_at) VALUES (3, 2, '安装与激活', 'installation-activation', '<h2>步骤一、下载并安装 Kiro</h2><p>前往 Kiro 官网下载对应系统版本。若电脑中已安装 Kiro，请先安装到 <code>1.0.437或以上</code>版本。</p><blockquote><p><strong>提示</strong></p><ul><li><p>插件仅支持 Kiro 1.0.437或以上 版本，若不是新安装，建议卸载重装，不要覆盖安装。</p></li><li><p>Mac 建议安装到默认应用目录，Windows 建议安装到默认目录。</p></li><li><p>安装后请检查本地版本是否正确。</p></li></ul></blockquote><blockquote><img src="https://YOUR-R2-PUBLIC-DOMAIN.example/relayrouter/docs/2026/09/6838e9aa-e603-4320-a445-a8455d7b1db2-image.png" alt="image.png"></blockquote><blockquote><img src="https://YOUR-R2-PUBLIC-DOMAIN.example/relayrouter/docs/2026/09/d4875558-9609-4e0e-ac62-1b5ef54b3f62-image.png" alt="image.png"></blockquote><h2>步骤二、安装扩展工具</h2><p>下载扩展工具 <code>.vsix</code> 文件，在 Kiro 中按 <code>Ctrl+Shift+X</code> 打开扩展中心，将文件拖入即可安装。</p><p>若无法拖拽安装，按 <code>Ctrl+Shift+P</code> 打开命令面板，输入 <code>Install from VSIX</code>，选择文件安装。</p><blockquote><img src="https://YOUR-R2-PUBLIC-DOMAIN.example/relayrouter/docs/2026/09/6f121408-927a-4948-8839-8eb2cd7e2a2a-image.png" alt="image.png"><p></p></blockquote><h2>步骤三、输入购买后的 CDK 激活码</h2><p>打开 Kiro 左侧边栏的 Kiro 授权页面，完整粘贴卡密，不要多输入空格，然后点击激活。</p><blockquote><p><strong>提示：</strong>显示“激活成功”后会强制刷新窗口，这是正常现象。授权面板显示当前账号信息后即可正常使用，有效期内同一设备无需重复激活。</p></blockquote><blockquote><img src="https://YOUR-R2-PUBLIC-DOMAIN.example/relayrouter/docs/2026/09/e2777123-bc9f-4185-8c59-c56b6fab4a5f-image.png" alt="image.png"></blockquote><blockquote><img src="https://YOUR-R2-PUBLIC-DOMAIN.example/relayrouter/docs/2026/09/6336756d-1621-46fb-9db1-1ed4c1ab20f5-image.png" alt="image.png"></blockquote><h2>步骤四、检查模型与功能</h2><p>激活成功后3秒界面会重启一下，是正常反应，这时候无需操作，原地等待，然后返回 Kiro，检查模型列表和相关功能是否正常显示。若未显示，请关闭本地 VPN 代理并重启 Kiro。</p><blockquote><img src="https://YOUR-R2-PUBLIC-DOMAIN.example/relayrouter/docs/2026/09/d31d916f-8104-436d-a9f3-a70f675533f6-image.png" alt="image.png"></blockquote><p></p>', 1, 'PUBLISHED', '2026-09-13 15:18:17.757738+08', '2026-09-13 15:18:17.757738+08', '2026-09-14 01:03:19.945847+08');
